import{c as a,Q as n,j as i,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Harmonised benchmarking of foundation models for single-cell and spatial transcriptomics reveals context-dependent generalisation","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.17227","title":"Harmonised benchmarking of foundation models for single-cell and spatial transcriptomics reveals context-dependent generalisation","archived_date":"2026-07-23T00:00:00.000Z","arxiv_id":2607.17227,"authors":["Sally Chen","Roxana Zahedi","Lucy Chhuo","Ricky Nguyen","Marjan BaghGolshani","Amin Beheshti","Mark Grosser","Min Yang","Nona Farbehi","Nigel Lovell","Ahmadreza Argha","Fatemeh Vafaee","Youqiong Ye","Hamid Alinejad-Rokny"],"domain":"genomic-biological-foundation-models","published_date":"2026-07-19T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-23-harmonised-benchmarking-single-cell-transcriptomics-2607-17227.md","filePath":"research/papers/2026-07-23-harmonised-benchmarking-single-cell-transcriptomics-2607-17227.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-07-23-harmonised-benchmarking-single-cell-transcriptomics-2607-17227.md"};function t(s,e,l,c,d,m){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="harmonised-benchmarking-of-foundation-models-for-single-cell-and-spatial-transcriptomics-reveals-context-dependent-generalisation" tabindex="-1">Harmonised benchmarking of foundation models for single-cell and spatial transcriptomics reveals context-dependent generalisation <a class="header-anchor" href="#harmonised-benchmarking-of-foundation-models-for-single-cell-and-spatial-transcriptomics-reveals-context-dependent-generalisation" aria-label="Permalink to &quot;Harmonised benchmarking of foundation models for single-cell and spatial transcriptomics reveals context-dependent generalisation&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文以統一（harmonised）評測框架，比較六個代表性單細胞/空間轉錄體基礎模型（Nicheformer、CellPLM、scGPT-spatial、GenePT、scELMo、Novae），涵蓋 scRNA-seq、空間轉錄體（spatial transcriptomics）、以及 Perturb-seq 三類資料型態。核心發現：這些基礎模型的泛化能力高度依賴訓練/測試資料的脈絡（context-dependent generalisation）——同一模型在不同組織類型、不同技術平台產生的資料上表現落差顯著，質疑「通用生物表徵」（universal biological representation）這一領域樂觀敘事的普適性，主張評測應納入脈絡遷移（context-shift）情境而非僅同分布測試集。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>單細胞/空間轉錄體基礎模型的跨脈絡泛化評測，是生物基礎模型評測方法論的最新分支，與 workspace 既有版圖完全不重疊；關鍵詞於既有覆蓋集合與既探勘新領域紀錄命中皆為 0。</p>',5)])])}const g=a(o,[["render",t]]);export{p as __pageData,g as default};
